[
  {
    "rule": "barrier",
    "path": "server/README.md",
    "reason": "the server's deploy/OAuth guide documents how the two halves relate (the extension manifest key, config.mjs client id, `cd ../extension` build) \u2014 cross-cutting setup docs, not a code coupling; the server ships no import of extension code"
  },
  {
    "rule": "barrier",
    "path": "extension/src/api.mjs",
    "reason": "a comment notes the server must allow X-Client-Version in CORS (template.yaml AllowHeaders) \u2014 documentation of the HTTP contract, not a code reference into server/"
  },
  {
    "rule": "claudinite-isolation",
    "path": "CLAUDE.md",
    "reason": "orientation prose only \u2014 the router names where the vendored canon lives so a reader knows the guidance is injected, not authored here; no code or content in this repo depends on the path"
  },
  {
    "rule": "claudinite-isolation",
    "path": "dev/procedures/working-instructions.md",
    "reason": "same orientation pointer \u2014 the working-instructions router says the general discipline is auto-injected from the vendored corpus rather than restated here, which is the sentence that stops the doc duplicating canon prose"
  }
]
---packs---
[
  "basics",
  {
    "id": "barriers",
    "config": {
      "rules": [
        {
          "between": [
            "server",
            "extension"
          ],
          "allow": [
            "shared"
          ],
          "reason": "the extension and its server integrate only through shared/ (the vendored single-source of categories/normalizeUrl) and the HTTP contract \u2014 never by referencing each other's code"
        }
      ]
    }
  },
  "chrome-extension",
  "executable-requirements",
  "git-github",
  "node",
  "spec-driven-product",
  "tidy-repo",
  "claudinite-growth",
  "local/tldr",
  {
    "id": "claude-code-web-users-support",
    "config": {
      "repo": "missingbulb/Shepherd"
    }
  },
  "claudinite-lifecycle"
]

