1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { migrationActive } from '../../engine/checks/helpers/active-migrations.mjs';
3	
4	// The Chrome-Web-Store release pipeline is VENDORED into each consumer's own
5	// .github/: the orchestrator (this STUB_FILE, named "Release to Chrome Store")
6	// owns the triggers and calls three LOCAL reusable workflows, which — with the
7	// privacy-page reusable and three composite actions — the pack materializes
8	// alongside it. Nothing references Claudinite's core .github/ any more; the whole
9	// set runs inside the repo. The pack keeps the copies in sync (baselining
10	// re-materializes on drift), so a consumer hosts the pipeline without owning it.
11	//
12	// The rename that made vendoring possible: the create-package reusable was
13	// `chrome-extension-release.yml` in the canon, which would collide with the
14	// orchestrator's own filename inside one repo, so it's vendored as
15	// `chrome-extension-create-package.yml`. STUB_FILE (the orchestrator) keeps its
16	// name — that's the fingerprint DESIGN.md pins the conformance suite to, and the
17	// failure-reporter issue keys ("Release: Create Package", …) live in the vendored
18	// reusables. The daily schedule is contract too: STUB_CRON pins every repo's
19	// nightly release to the same anchor. The privacy page has no orchestrator entry of
20	// its own: it redeploys as part of every publish (the publish reusable's
21	// deploy-privacy-page leg).
22	//
23	// Migration tolerance: while `chrome-release-vendoring` is recent, a repo still
24	// on the pre-vendoring shape (the orchestrator calling Claudinite's core
25	// workflows @main) is TOLERATED — baselining vendors it, no red window. Once the
26	// record ages out of the recency window, migrationActive() flips false and the
27	// tolerance is gone: every up-to-date repo has vendored by then, and a repo
28	// still on @main is flagged.
29	export const STUB_FILE = 'chrome-extension-release.yml';
30	export const STUB_NAME = 'Release to Chrome Store';
31	export const LEGACY_STUB_NAMES = ['Release'];
32	export const STUB_CRON = '30 0 * * *';
33	
34	// The create-package reusable's canon filename (pre-vendoring), still the name a
35	// legacy orchestrator calls @main — kept for the fingerprint + tolerance.
36	export const LEGACY_CREATE_PACKAGE = 'chrome-extension-release.yml';
37	// Its vendored filename (renamed to avoid colliding with the orchestrator).
38	export const VENDORED_CREATE_PACKAGE = 'chrome-extension-create-package.yml';
39	
40	// The reusable workflows the orchestrator calls locally.
